from django.db.models import Q
from django.utils import timezone


def mark_awaiting_result(apps, schema_editor):
    """Retire the Live status and mark past-deadline matches Awaiting result.

    Live rows become Finished (result entered), Awaiting result (deadline
    passed) or Scheduled (still open). Scheduled matches already past their
    deadline with no result become Awaiting result.
    """
    Match = apps.get_model("predictions", "Match")
    now = timezone.now()
    live = Match.objects.filter(status="live")
    live.filter(Q(winner__isnull=False) | Q(is_draw=True)).update(status="finished")
    live.filter(prediction_deadline__lte=now).update(status="awaiting_result")
    live.update(status="scheduled")
    Match.objects.filter(
        status="scheduled",
        prediction_deadline__lte=timezone.now(),
        winner__isnull=True,
        is_draw=False,
    ).update(status="awaiting_result")


